import sys

def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                j += 1
            tokens.append(float(s[i:j]))
            i = j
        else:
            raise ValueError(f"Invalid character: {c}")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        val = self.expr()
        if self.pos != len(self.tokens):
            raise ValueError("Unexpected token")
        return val

    def expr(self):
        val = self.term()
        while self.peek() in ('+', '-'):
            op = self.next()
            rhs = self.term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def term(self):
        val = self.factor()
        while self.peek() in ('*', '/'):
            op = self.next()
            rhs = self.factor()
            if op == '*':
                val = val * rhs
            else:
                if rhs == 0:
                    raise ValueError("Division by zero")
                val = val / rhs
        return val

    def factor(self):
        tok = self.peek()
        if tok == '(':
            self.next()
            val = self.expr()
            if self.next() != ')':
                raise ValueError("Expected ')'")
            return val
        if tok == '-':
            self.next()
            return -self.factor()
        if tok == '+':
            self.next()
            return self.factor()
        if isinstance(tok, float):
            self.next()
            return tok
        raise ValueError(f"Unexpected token: {tok}")

def format_result(val):
    if abs(val - round(val)) < 1e-9:
        return str(int(round(val)))
    return f"{val:.6f}".rstrip('0').rstrip('.')

def main():
    line = sys.stdin.readline().strip()
    parts = line.split(None, 1)
    if len(parts) < 2 or parts[0] != 'calc':
        print("Error: expected command format 'calc <expression>'")
        return
    try:
        tokens = tokenize(parts[1])
        result = Parser(tokens).parse()
        print(format_result(result))
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()
